from abc import ABC
from typing import Optional

class RFSwitch(ABC):
    def __init__(self, ip: str, model: Optional[str] = None, port: Optional[int] = None,
                 rf_switch_port_numbers: Optional[list[int]] = None) -> None:
        """
        :param ip: ip_address of switch
        :param model: model of the RF switch
        :param port: port to connect to, defaults to None
        """
        self.ip = ip
        self.port = port
        self.model = model
        self.vendor = self.__class__.__name__
        self.rf_switch_ports = {i: RFSwitchPort(self, i) for i in
                                rf_switch_port_numbers} if rf_switch_port_numbers else None

class RFSwitchPort:
    def __init__(self, rf_switch: RFSwitch, port_no: int) -> None:
        """
        :param rf_switch: object of subclass of RFSwitch
        :param port_no: Port number on the RF switch
        """
        self.rf_switch = rf_switch
        self.port_no = port_no


class RFLight(RFSwitch):
    def __init__(self, ip: str, model: Optional[str] = None, port: Optional[int] = None) -> None:
        super().__init__(ip, model, port)


