class MiniCircuits(RFSwitch):
    def __init__(self, ip: str, model: Optional[str] = None, port: Optional[int] = None,
                 password: Optional[str] = None) -> None:
        """
        Initialize a MiniCircuits switch.

        :param ip: IP address of the switch
        :param model: Model of the RF switch, defaults to None
        :param port: Port to connect to, defaults to None
        :param password: Password for HTTP connection, defaults to None
        """
        super().__init__(ip, model, port)
        self.password = password


class RPI(RFSwitch):
    def __init__(self, ip: str, model: Optional[str] = None, port: Optional[int] = None,
                 username: Optional[str] = None, password: Optional[str] = None) -> None:
        """
        Initialize an RPI switch.

        :param ip: IP address of the switch
        :param model: Model of the RF switch, defaults to None
        :param port: Port to connect to, defaults to None
        :param username: Username for authentication, defaults to None, mandatory for setup in taf.hw.rf_switch
        :param password: Password for authentication, defaults to None, mandatory for setup in taf.hw.rf_switch
        """
        super().__init__(ip, model, port)
        self.username = username
        self.password = password
